-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["171f283d5c3edcfa"] = { "Ieri notte è riuscito a parlare per la prima volta. È un druido di nome Heralath, mandato in queste terre a indagare sulle voci del dio cinghiale caduto.\n\nCon voce debole mi ha detto di credere che il grande teschio di cinghiale sia il luogo in cui il grande dio cinghiale Agamaggan cadde combattendo la Legione Infuocata, circa 10,000 anni fa, durante la Guerra degli Antichi. Il suo corpo immenso spianò la terra e il suo sangue penetrò nel suolo. Contorte guglie di spine crescono dove cadde il suo sangue...", "." },
  ["174a3432104c3294"] = { "⟦Executor Zygand=Esecutore Zygand⟧,\n\nritengo che il Flagello che vediamo sempre più nell'entroterra non sia dovuto a un cedimento delle nostre difese. Osservo da tempo le nostre forze alla ⟦Bulwark=Granbarricata⟧ e al posto di sosta orientale, e ci vorrebbe un vero e proprio esercito per sfondare.\n\nSospetto piuttosto che vengano creati di recente da qualche nemico invisibile all'interno dei nostri confini. Continuerò a seguire questa pista, nella speranza di fermare questi episodi alla fonte.\n\n--Kristof", "." },
  ["178c16ff6dc309c5"] = { "I tauren\n\nI tauren, con la loro concezione sciamanica dell'inverno e il loro recente avvicinamento alle pratiche druidiche, si accordano bene con la leggenda del Grande Inverno. Si concentrano però quasi del tutto sugli aspetti di rinnovamento della tradizione, e lasciano il culto della leggenda alle razze (secondo loro) meno in sintonia con la natura delle cose. Molti tauren scelgono questo periodo come il momento giusto per rendere grazie delle benedizioni della loro nuova patria a Mulgore.", "." },
  ["17944af3b2dd69dc"] = { "Al mio onorato re,\n\nnon spetta alla moglie di un umile soldato mettere in discussione le azioni di grandi condottieri come te. Le battaglie che infuriano nelle nostre terre si combattono per preservare la vita grandiosa che conosciamo e amiamo, dalle fresche acque di Loch Modan alle frizzanti vette innevate di Dun Morogh.", "." },
  ["1797a5833ec7b615"] = { "Racconto di Gri'lek il Viandante\n\n[...L'inizio della tavoletta era consumato e cancellato. Ma la fine era leggibile...]\n\nGri'lek avanzava a passi pesanti nella giungla. I suoi occhi bruciavano e il suo petto rombava, perché in lui c'era una grande collera.\n\nFurioso, ruggì verso il cielo e alzò il braccio. Alzò il braccio sinistro, divenuto forte e sicuro cacciando senza il suo gemello.\n\nPerché il braccio destro di Gri'lek non c'era più, e non sarebbe tornato.", "." },
  ["17d8755d6124c4b6"] = { "Malfurion, convinto che il ⟦Well of Eternity=Pozzo dell'Eternità⟧ fosse il cordone ombelicale che legava i demoni al mondo fisico, insistette perché venisse distrutto. I suoi compagni, sapendo che il Pozzo era la fonte della loro immortalità e dei loro poteri, furono inorriditi dall'idea avventata. Eppure Tyrande comprese la saggezza della teoria di Malfurion, e così convinse Cenarius e i loro compagni ad assaltare il tempio di Azshara e a trovare il modo di chiudere il Pozzo per sempre.", "." },
})
